// Makes form uploads and email attachments look identical downstream.
// Output: one item per PDF, file always in binary "data".
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const isEmail = !!(j.threadId || j.from || j.headers);
  const source = isEmail ? 'email' : 'form';
  const sender = isEmail
    ? (j.from?.value?.[0]?.address || j.from?.text || '')
    : (j['Your Email'] || '');
  const receivedAt = isEmail
    ? (j.date ? new Date(j.date).toISOString() : new Date().toISOString())
    : (j.submittedAt ? new Date(j.submittedAt).toISOString() : new Date().toISOString());

  const files = item.binary || {};
  for (const key of Object.keys(files)) {
    const f = files[key];
    const name = f.fileName || key;
    const isPdf = (f.mimeType || '').toLowerCase().includes('pdf') || name.toLowerCase().endsWith('.pdf');
    if (!isPdf) continue; // skip logos, signatures, other attachments

    out.push({
      json: {
        source,
        sender,
        email_subject: isEmail ? (j.subject || '') : '',
        email_message_id: isEmail ? (j.id || '') : '',
        submitter_notes: isEmail ? '' : (j['Notes'] || ''),
        file_name: name,
        received_at: receivedAt
      },
      binary: { data: f }
    });
  }
}
return out;

// AI READS, CODE CHECKS.
// Nothing the AI returns is trusted until it passes these rules.
const APPROVAL_THRESHOLD = 500;   // USD. Approval needed when total > this.
const EXPECTED_CURRENCY = 'USD';
const CATEGORIES = ['Office Supplies','Software & Subscriptions','Utilities & Internet','Professional Services','Marketing & Creative','Meals & Catering','Shipping & Courier','Facilities & Cleaning','Equipment','Other'];

const intake = $('Ready for AI Extraction').item;
const src = intake.json;
// The PDF file itself: taken from Normalize Intake, the one node that always carries it.
const pdfFile = $('Normalize Intake').item.binary;
const pdfText = (src.invoice_text || '');
const errors = [];

// 1. Read the AI's answer.
// In JSON mode n8n usually hands us parsed fields directly ($json.vendor_name...).
// If it ever arrives as raw text instead, parse it (and strip ```json fences).
let ai = {};
if ($json && typeof $json.text === 'string') {
  try {
    ai = JSON.parse($json.text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim());
  } catch (e) {
    errors.push('AI response was not valid JSON');
  }
} else if ($json && typeof $json.text === 'object' && $json.text !== null) {
  ai = $json.text;
} else if ($json && ('vendor_name' in $json || 'total' in $json)) {
  ai = $json;
} else {
  errors.push('AI returned no usable data');
}

const toNum = v => (v === null || v === undefined || v === '') ? null
  : (typeof v === 'number' ? v : parseFloat(String(v).replace(/[^0-9.\-]/g, '')));
const clean = v => (v === null || v === undefined || String(v).trim() === '' || String(v).toLowerCase() === 'null') ? null : String(v).trim();

const vendor   = clean(ai.vendor_name);
const invNo    = clean(ai.invoice_number);
const invDate  = clean(ai.invoice_date);
const dueDate  = clean(ai.due_date);
const currency = clean(ai.currency);
const subtotal = toNum(ai.subtotal);
const tax      = toNum(ai.tax);
const total    = toNum(ai.total);
// Category: must be one of our fixed list. Anything else becomes 'Other' (not a failure, just less precise).
const rawCat   = clean(ai.category);
const category = CATEGORIES.includes(rawCat) ? rawCat : 'Other';

// 2. Required fields
if (!vendor)  errors.push('Missing vendor name');
if (!invNo)   errors.push('Missing invoice number');
if (!invDate) errors.push('Missing invoice date');
if (total === null || isNaN(total)) errors.push('Missing total');

// 3. Math: subtotal + tax must equal total (1-cent tolerance)
if (subtotal !== null && total !== null && !isNaN(total)) {
  const expected = Math.round((subtotal + (tax || 0)) * 100) / 100;
  if (Math.abs(expected - total) > 0.01) {
    errors.push(`Math error: subtotal ${subtotal.toFixed(2)} + tax ${(tax || 0).toFixed(2)} = ${expected.toFixed(2)}, but invoice total is ${total.toFixed(2)}`);
  }
} else if (subtotal === null) {
  errors.push('Missing subtotal (cannot verify math)');
}
if (total !== null && total <= 0) errors.push('Total must be greater than 0');

// 4. Date sanity
const today = $now.setZone('Asia/Manila').toISODate();
const isValidDate = d => /^\d{4}-\d{2}-\d{2}$/.test(d) && DateTime.fromISO(d).isValid;
if (invDate && !isValidDate(invDate)) errors.push(`Invoice date not a valid date: ${invDate}`);
if (invDate && isValidDate(invDate) && invDate > today) errors.push(`Invoice date ${invDate} is in the future`);
if (invDate && isValidDate(invDate) && invDate < DateTime.fromISO(today).minus({ years: 1 }).toISODate()) errors.push(`Invoice date ${invDate} is over a year old`);
if (dueDate && invDate && isValidDate(dueDate) && isValidDate(invDate) && dueDate < invDate) errors.push('Due date is before invoice date');

// 5. Currency
if (currency && currency.toUpperCase() !== EXPECTED_CURRENCY) errors.push(`Unexpected currency: ${currency}`);

// 6. Hallucination guard: AI values must actually appear in the PDF text
const textNoSpaces = pdfText.replace(/\s+/g, '');
if (invNo && !textNoSpaces.includes(invNo.replace(/\s+/g, ''))) errors.push(`AI invoice number "${invNo}" not found in PDF text`);
if (total !== null && !isNaN(total)) {
  const withCommas = total.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (!pdfText.includes(withCommas) && !pdfText.includes(total.toFixed(2))) errors.push(`AI total ${total.toFixed(2)} not found in PDF text`);
}

// 7. Keys for later steps
const normalize = s => (s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const duplicateKey = (vendor && invNo) ? `${normalize(vendor)}|${normalize(invNo)}` : '';
// Unique per invoice, even when several arrive in the same run
const suffix = Math.random().toString(36).slice(2, 6).toUpperCase();

return {
  json: {
    record_id: `R-${$now.setZone('Asia/Manila').toFormat('yyyyLLdd-HHmmss')}-${suffix}`,
    received_at: src.received_at,
    source: src.source,
    sender: src.sender,
    file_name: src.file_name,
    email_message_id: src.email_message_id,
    submitter_notes: src.submitter_notes,
    vendor_name: vendor,
    invoice_number: invNo,
    invoice_date: invDate,
    due_date: dueDate,
    currency: currency ? currency.toUpperCase() : null,
    subtotal,
    tax,
    total,
    category,
    line_items_summary: clean(ai.line_items_summary),
    ai_confidence: clean(ai.confidence) || 'unknown',
    duplicate_key: duplicateKey,
    validation_status: errors.length ? 'Failed' : 'Passed',
    validation_errors: errors.join('; '),
    approval_required: total !== null && total > APPROVAL_THRESHOLD
  },
  binary: pdfFile
};

// Is this invoice already in the Register?
// Duplicate = same vendor + same invoice number (the duplicate_key),
// where the earlier row is still 'live' (not rejected / flagged / itself a duplicate).
const LIVE_STATUSES = ['Approved (auto)', 'Awaiting Approval', 'Approved', 'Paid'];

const existing = {};
for (const r of $input.all().map(i => i.json)) {
  if (r && r.duplicate_key && LIVE_STATUSES.includes(String(r.status || ''))) {
    existing[String(r.duplicate_key)] = r.record_id || `row ${r.row_number}`;
  }
}

// Also catch the same invoice arriving twice in ONE run (e.g. two emails at once)
const seenThisRun = {};

return $('Passed: Next = Duplicate Check').all().map(item => {
  const key = item.json.duplicate_key;
  let duplicateOf = '';
  if (key && existing[key]) duplicateOf = existing[key];
  else if (key && seenThisRun[key]) duplicateOf = seenThisRun[key];
  if (key && !duplicateOf) seenThisRun[key] = item.json.record_id;

  return {
    json: { ...item.json, is_duplicate: !!duplicateOf, duplicate_of: duplicateOf },
    binary: item.binary
  };
});

// Turn the approver's click into audit fields.
// The Gmail node only returns { data: { approved, respondedAt } },
// so we pull the invoice data + PDF back from the node before it.
const APPROVER = 'approver@yourcompany.com';
const original = $('Needs Approval?').item;
const d = ($json && $json.data) || {};

let status, approvalStatus, approvedBy = '', reason = '';
if (d.approved === true) {
  status = 'Approved'; approvalStatus = 'Approved'; approvedBy = APPROVER;
} else if (d.approved === false) {
  status = 'Rejected'; approvalStatus = 'Rejected'; approvedBy = APPROVER;
  reason = 'Rejected by approver';
} else {
  status = 'Needs Review'; approvalStatus = 'No response (timed out)';
  reason = 'Approval request timed out after 3 days';
}

return {
  json: {
    ...original.json,
    status,
    approval_status: approvalStatus,
    approved_by: approvedBy,
    decided_at: d.respondedAt || $now.toISO(),
    review_reason: reason
  },
  binary: original.binary
};
